TABLES = {"es": ES, "pt": PT}
# Roles and the categories on the archive, kept from the earlier translations
ROLES = {
    "es": {"Chairman": "Presidenta", "Secretary": "Secretario", "Treasurer": "Tesorero",
           "Member and Operations Coordinator": "Miembro y coordinador de operaciones", "Member and Accountant": "Miembro y contable",
           "conservation": "conservación", "philanthropy": "filantropía"},
    "pt": {"Chairman": "Presidente", "Secretary": "Secretário", "Treasurer": "Tesoureiro",
           "Member and Operations Coordinator": "Membro e coordenador de operações", "Member and Accountant": "Membro e contador",
           "conservation": "conservação", "philanthropy": "filantropia"},
}


def translate_html(html: str, table: dict) -> str:
    """Translate the paragraph texts inside the WordPress export, leaving markup and images alone."""
    import re
    def repl(m):
        inner = m.group(2)
        key = re.sub(r"\s+", " ", inner).strip()
        for k, v in table.items():
            if re.sub(r"\s+", " ", k).strip() == key:
                return m.group(1) + v + m.group(3)
        return m.group(0)
    # innermost paragraphs only: the export nests <p> inside theme wrapper <p> tags
    html = re.sub(r"(<p\b[^>]*>)((?:(?!<p\b)[\s\S])*?)(</p>)", repl, html)
    # the alt text of each photograph, looked up like any other string
    return re.sub(r'(\balt=")([^"]*)(")', lambda m: m.group(1) + table.get(m.group(2), m.group(2)) + m.group(3), html)


def build(locale: str, en: dict, previous: dict) -> tuple[dict, list[str]]:
    table = TABLES[locale]; roles = ROLES[locale]; missing: list[str] = []
    bios = {m["name"]: m for b in next(p for p in previous["pages"] if p["slug"] == "/about")["blocks"] if b["type"] == "team" for m in b["items"]}

    def walk(node, path):
        if isinstance(node, dict):
            out = {}
            for k, v in node.items():
                if k == "name" and isinstance(v, str) and v in roles:        # project category names
                    out[k] = roles[v]
                elif k in STRUCTURAL and not (k == "projects" and v and isinstance(v, list) and isinstance(v[0], dict)):
                    out[k] = v          # `projects` is structural only as a list of slugs, not the archive itself
                elif k == "content" and isinstance(v, str) and "<p" in v:
                    out[k] = translate_html(v, table)
                elif k == "bio" and node.get("name") in bios:
                    out[k] = bios[node["name"]]["bio"]          # already translated earlier
                elif k == "role" and isinstance(v, str):
                    prev = bios.get(node.get("name"), {}).get("role")
                    out[k] = prev if prev and prev != v else roles.get(v, v)   # keep the earlier translation where it exists
                elif k == "altText" and isinstance(v, str):
                    out[k] = table.get(v, v) if v in table else (missing.append(v) or v)
                else:
                    out[k] = walk(v, path + [k])
            return out
        if isinstance(node, list):
            return [walk(x, path + [str(i)]) for i, x in enumerate(node)]
        if isinstance(node, str) and node.strip():
            if node in table: return table[node]
            if node in roles: return roles[node]
            # a multi-paragraph string assembled from translated paragraphs (the donate stories)
            if "\n\n" in node:
                parts = re.split(r"\n\s*\n", node)
                if all(x.strip() in table or not x.strip() for x in parts):
                    return "\n\n".join(table[x.strip()] if x.strip() else x for x in parts)
            if node in PASS_THROUGH or not any(c.isalpha() for c in node): return node
            missing.append(node); return node
        return node

    return walk(en, []), missing


if __name__ == "__main__":
    en = json.loads((ROOT / "data/data.json").read_text(encoding="utf-8"))
    for locale in ("es", "pt"):
        previous = json.loads((ROOT / f"data/data.{locale}.json").read_text(encoding="utf-8"))
        out, missing = build(locale, en, previous)
        (ROOT / f"data/data.{locale}.json").write_text(json.dumps(out, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
        uniq = sorted(set(missing))
        print(f"{locale}: written; {len(uniq)} strings still in English")
        for m in uniq: print("   -", m[:110])
